def _preferred_cloud() -> str:
    """Which cloud's env mirror to prefer for downloads.

    - On GCP (``QBRAID_CLOUD`` contains ``GCP``): prefer ``gcp`` (canonical is
      already GCS, so we skip the mirror lookup entirely — same-cloud, no egress).
    - Everywhere else (Azure pods, local dev, other clouds): prefer ``azure``.
      Azure has favorable egress economics for qBraid and generally covers user
      downloads on our credits.

    Ops can force canonical (skip the mirror pick) by setting
    ``QBRAID_PREFER_MIRROR=canonical`` — useful as a break-glass if the Azure
    mirror is degraded or credits are exhausted.
    """
    if os.environ.get("QBRAID_PREFER_MIRROR", "").lower() == "canonical":
        return "gcp"
    cloud = os.environ.get("QBRAID_CLOUD", "").upper()
    return "gcp" if "GCP" in cloud else "azure"


def _cloud_of_uri(uri: str) -> Optional[str]:
    """Classify a mirror URI by its cloud provider from the URL alone.

    Returns ``'gcp'``, ``'azure'``, or ``None`` for unrecognized URIs. Kept
    intentionally naive — the API's URI validation is authoritative; this is
    only used to sort candidates by cloud on the client side.
    """
    if uri.startswith("gs://") or "storage.googleapis.com" in uri:
        return "gcp"
    if ".blob.core.windows.net" in uri:
        return "azure"
    return None


_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)


def _parse_uploaded_at(raw: Any) -> datetime:
    """Parse an ``uploadedAt`` ISO string to a comparable datetime.

    Returns ``_EPOCH`` for missing/non-string/unparseable values so malformed
    entries sink to last in a newest-first sort instead of winning ties by
    lexicographic accident (``"Z"`` > ``"+"`` > empty string).
    """
    if not isinstance(raw, str):
        return _EPOCH
    try:
        # fromisoformat handles the trailing "Z" natively on 3.11+; qbraid-core
        # requires >=3.10 so on 3.10 we swap the Z for +00:00 defensively.
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return _EPOCH


def _pick_mirror_uri(env_mirrors: Optional[dict]) -> Optional[str]:
    """Pick a mirror URI matching :func:`_preferred_cloud`, newest first.

    ``env_mirrors`` is the raw ``envMirrors`` map from the API — keyed by
    ``clusterId`` with entries of the shape ``{uri, uploadedAt, byteSize?}``.
    Returns ``None`` to signal "use canonical" — either because the preferred
    cloud is GCS (canonical is already GCS, so no mirror needed), the map isn't
    a dict, or no matching mirror exists in it.
    """
    preferred = _preferred_cloud()
    # GCP-preferred callers download canonical directly; skipping the mirror
    # scan avoids paying the /execute URI-validation branch for the common case.
    if preferred == "gcp":
        return None
    # Belt-and-braces: the API contract types this as an object, but a bad
    # payload shouldn't crash the install path.
    if not isinstance(env_mirrors, dict):
        return None
    candidates: list[tuple[datetime, str]] = []
    for mirror in env_mirrors.values():
        if not isinstance(mirror, dict):
            continue
        uri = mirror.get("uri")
        if uri and _cloud_of_uri(uri) == preferred:
            candidates.append((_parse_uploaded_at(mirror.get("uploadedAt")), uri))
    candidates.sort(reverse=True)
    return candidates[0][1] if candidates else None


def _detect_user_home_patterns() -> list[tuple[str, str]]:
    """Detect user-specific path patterns to sanitize.

    Returns:
        List of (pattern, replacement) tuples for path sanitization
    """
    patterns = []

    # Get current user's home directory
    home = str(Path.home())

    # Unix-style home directories
    if home.startswith("/Users/"):  # macOS
        # /Users/username/... -> ~/.qbraid/environments/...
        patterns.append((home, "~"))
    elif home.startswith("/home/"):  # Linux
        # /home/username/... -> ~/.qbraid/environments/...
        patterns.append((home, "~"))

    # Windows-style home directories
    if os.name == "nt":
        # C:\Users\username\... -> ~/.qbraid/environments/...
        # Also handle forward slash variants
        patterns.append((home.replace("\\", "/"), "~"))
        patterns.append((home, "~"))

    # Also detect from environment variables
    for env_var in ["HOME", "USERPROFILE", "HOMEPATH"]:
        env_home = os.environ.get(env_var)
        if env_home and env_home != home:
            patterns.append((env_home, "~"))
            if os.name == "nt":
                patterns.append((env_home.replace("\\", "/"), "~"))

    return patterns


def _sanitize_path_for_upload(content: str, slug: str) -> str:
    """Sanitize paths in file content for upload.

    Replaces user-specific paths with generic placeholders that can be
    expanded on download to the target system.

    Args:
        content: File content to sanitize
        slug: Environment slug for replacement path

    Returns:
        Sanitized content
    """
    # Target path pattern for uploaded environments
    target_path = f"/home/jovyan/.qbraid/environments/{slug}"

    # Detect and replace user-specific paths
    patterns = _detect_user_home_patterns()

    result = content

    for pattern, _ in patterns:
        # Replace full paths that contain .qbraid/environments
        # e.g., /Users/kanav/.qbraid/environments/myenv_abc123/pyenv
        #    -> /home/jovyan/.qbraid/environments/slug/pyenv
        qbraid_pattern = re.compile(
            re.escape(pattern) + r"/\.qbraid/environments/[^/]+",
            re.IGNORECASE if os.name == "nt" else 0,
        )
        result = qbraid_pattern.sub(target_path, result)

    return result


def _sanitize_shebang_for_upload(content: bytes, slug: str) -> bytes:
    """Sanitize shebang line for upload.

    Args:
        content: File content (binary)
        slug: Environment slug

    Returns:
        Sanitized content
    """
    if not content.startswith(b"#!"):
        return content

    # Split into shebang and rest
    newline_idx = content.find(b"\n")
    if newline_idx == -1:
        return content

    shebang = content[:newline_idx].decode("utf-8", errors="ignore")
    rest = content[newline_idx:]

    # Check if this is a Python shebang
    if "python" not in shebang.lower():
        return content

    # Replace with generic path
    target_python = f"/home/jovyan/.qbraid/environments/{slug}/pyenv/bin/python3"
    new_shebang = f"#!{target_python}"

    return new_shebang.encode("utf-8") + rest


@register_client()
class EnvironmentManagerClient(QbraidClientV1):
    """Client for interacting with qBraid environment services."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.envs_paths = get_default_envs_paths()

    @property
    def envs_paths(self) -> list[Path]:
        """Returns a dictionary of environment paths.

        Returns:
            A dictionary containing the environment paths.
        """
        return self._envs_paths

    @envs_paths.setter
    def envs_paths(self, value: list[Path]):
        """Sets the qBraid environments paths."""
        self._envs_paths = value

    @staticmethod
    def _extract_data(response: dict) -> Any:
        """Extract data from API response, handling both response formats.

        Supports:
            {"success": true, "data": ...}
            {"status": "success", "data": ...}
        """
        if isinstance(response, dict) and "data" in response:
            status_ok = response.get("success") or response.get("status") == "success"
            if status_ok:
                return response["data"]
        return response

    def resolve_logos(self, provider_name: str) -> dict:
        """Resolve provider name to logo URLs via the providers API.

        Looks up the provider by name from GET /providers and returns
        the logo URLs from the provider document. No fuzzy matching —
        exact case-insensitive match on the provider name.

        Args:
            provider_name: Provider name (e.g., "ibm", "nvidia", "google").

        Returns:
            Dict with "light" and "dark" logo URL keys.

        Raises:
            ValueError: If provider not found.
            EnvironmentServiceRequestError: If API request fails.
        """
        try:
            from qbraid_core.services.runtime import QuantumRuntimeClient

            runtime_client = QuantumRuntimeClient(session=self.session)
            providers = runtime_client.list_providers()
        except Exception as err:
            raise EnvironmentServiceRequestError(
                f"Failed to fetch providers for logo resolution: {err}"
            ) from err

        key = provider_name.lower()
        for provider in providers:
            if provider.provider.lower() == key:
                if provider.logo:
                    return {
                        "light": provider.logo.light,
                        "dark": provider.logo.dark,
                    }
                return {"light": None, "dark": None}

        available = [p.provider for p in providers]
        raise ValueError(f"Provider '{provider_name}' not found. Available: {', '.join(available)}")

    def remote_publish_environment(
        self,
        config: Optional[EnvironmentConfig] = None,
        file_path: Optional[str] = None,
        persist_env: Optional[bool] = False,
    ) -> dict:
        """Triggers the remote publish of a custom environment.

        Args:
            config: Environment configuration.
            file_path: Path to the environment YAML file.
            persist_env: Whether to persist the environment in user space.

        Returns:
            A dictionary containing the response data.
        """
        if config and file_path:
            raise ValueError(
                "Only one of YAML file or config data can be provided for env creation"
            )

        if not config and not file_path:
            raise ValueError("Either YAML file or config data must be provided for env creation")

        # 1. Prepare request body
        req_body = {
            "persistEnv": persist_env,
            "config": config.model_dump_json(by_alias=True) if config else None,
        }

        req_files = {}
        open_files = []

        try:
            if file_path:
                if not Path(file_path).exists():
                    raise ValueError(f"Env config file not found at path: {file_path}")
                yaml_file = open(file_path, "rb")
                open_files.append(yaml_file)
                req_files["yamlFile"] = (Path(file_path).stem, yaml_file, "text/yaml")

            env_publish_data = self.session.post(
                "/environments/remote/publish",
                data=req_body,
                files=req_files if req_files else None,
            ).json()

        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Remote publish environment request failed: {err}"
            ) from err
        finally:
            for f in open_files:
                f.close()

        if (
            env_publish_data is None
            or len(env_publish_data) == 0
            or env_publish_data.get("envSlug") is None
        ):
            raise EnvironmentServiceRequestError(
                f"Remote publish environment request responded with invalid data: "
                f"{env_publish_data}",
            )

        return env_publish_data

    def retrieve_remote_publish_status(self, env_slug: str) -> dict:
        """Retrieves the status of the remote publish request for the given environment slug.

        Args:
            env_slug: The slug of the environment to retrieve the status for.

        Returns:
            A dictionary containing the response data.
        """
        try:
            env_publish_status = self.session.get(
                "/environments/remote/publish/status", params={"envSlug": env_slug}
            ).json()
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Request failed to retrieve remote publish status: {err}"
            ) from err

        if (
            env_publish_status is None
            or len(env_publish_status) == 0
            or env_publish_status.get("status") is None
        ):
            raise EnvironmentServiceRequestError(
                f"Request failed to retrieve remote publish status: {env_publish_status}",
            )

        return env_publish_status["status"]

    def wait_for_env_remote_publish(
        self, env_slug: str, timeout: Optional[int] = None, poll_interval: int = 20
    ) -> bool:
        """Monitors the remote publish status of the given environment slug by polling the remote
        create status field.

        Args:
            env_slug: The slug of the environment to monitor the status for.
            timeout: The maximum time to wait for the remote publish to complete.
            poll_interval: The time interval in seconds to poll the remote publish
                           status.
        Raises:
            TimeoutError: If the remote publish status is not complete within the timeout period.

        Returns:
            success: True if the remote publish was successful, False otherwise.
        """
        # default wait time is 10 minutes
        retries = timeout // poll_interval if timeout else 30
        status = None

        for retry in range(retries):
            status = self.retrieve_remote_publish_status(env_slug)
            logger.info("Remote publish status: %s", status)
            if status in ["COMPLETE", "FAILED"]:
                break

            if retry == retries - 1:
                raise TimeoutError(
                    f"Remote env publish not complete within timeout period, final status: {status}"
                )

            logger.info("Retrying in %d seconds", poll_interval)
            time.sleep(poll_interval)

        return status == "COMPLETE"

    def create_environment(
        self,
        config: EnvironmentConfig,
        logo_light_url: Optional[str] = None,
        logo_dark_url: Optional[str] = None,
    ) -> dict[str, Any]:
        """Creates a new environment with the given configuration.

        Args:
            config: Environment configuration.
            logo_light_url: URL to light theme logo image (from S3).
            logo_dark_url: URL to dark theme logo image (from S3).

        Returns:
            A dictionary containing the environment data.

        Raises:
            ValueError: If the environment name is invalid or the description is too long.
            EnvironmentServiceRequestError: If the create environment request fails.
        """
        if not is_valid_env_name(config.name):
            raise ValueError(f"Invalid environment name: {config.name}")

        if config.description and len(config.description) > 500:
            raise ValueError("Description is too long. Maximum length is 500 characters.")

        # Build form data
        req_data: dict[str, Any] = {
            "name": config.name,
        }

        if config.description:
            req_data["description"] = config.description

        if config.tags:
            tags = config.tags if isinstance(config.tags, str) else ",".join(config.tags)
            req_data["tags"] = tags

        if config.visibility:
            req_data["visibility"] = config.visibility

        if config.kernel_name:
            req_data["kernelName"] = config.kernel_name

        if config.shell_prompt:
            req_data["prompt"] = config.shell_prompt

        if config.python_version:
            req_data["pythonVersion"] = config.python_version

        if config.platform:
            req_data["platform"] = config.platform

        if config.group_slug:
            req_data["groupSlug"] = config.group_slug

        if config.python_packages:
            req_data["packages"] = [
                (
                    f"{name}=={version}"
                    if version and not version.startswith(("=", ">", "<", "~", "!"))
                    else f"{name}{version}"
                )
                for name, version in config.python_packages.items()
            ]

        # Resolve logo URLs from provider name if provided
        if not logo_light_url and not logo_dark_url and config.logo:
            try:
                resolved = self.resolve_logos(config.logo)
                logo_light_url = resolved.get("light")
                logo_dark_url = resolved.get("dark")
            except (ValueError, EnvironmentServiceRequestError) as err:
                logger.warning("Failed to resolve logos for '%s': %s", config.logo, err)

        # Send logo URLs as string form-data fields
        if logo_light_url:
            req_data["logoLight"] = logo_light_url
        if logo_dark_url:
            req_data["logoDark"] = logo_dark_url

        try:
            response = self.session.post("/environments", data=req_data).json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                data = response["data"]
                env_data = data.get("environment", data)
            else:
                env_data = response

        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Create environment request failed: {err}"
            ) from err

        if env_data is None or len(env_data) == 0 or env_data.get("slug") is None:
            raise EnvironmentServiceRequestError(
                "Create environment request responded with invalid environment data"
            )

        return env_data

    def delete_environment(self, slug: str) -> None:
        """Deletes the environment with the given slug.

        Args:
            slug: The slug of the environment to delete.

        Returns:
            None

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the delete environment request fails.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            self.session.delete(f"/environments/{slug}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Delete environment request failed: {err}"
            ) from err

    def update_environment(self, slug: str, **kwargs) -> dict[str, Any]:
        """Update environment metadata.

        Args:
            slug: The slug of the environment to update.
            **kwargs: Fields to update. Supported fields include:
                - name: Display name for the environment. (The legacy
                        ``displayName`` key is accepted and mapped to ``name``.)
                - description: Environment description
                - tags: List of tags
                - visibility: 'public' or 'private'

                Note: ``logo`` is not applied through this route — the API
                ignores it here. Logos are managed via a separate mechanism.

        Returns:
            Dictionary containing the updated environment data.

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the update request fails.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        # The API's display-name field is `name`. Older callers pass the legacy
        # `displayName` (this client's previous contract), which the API now
        # silently ignores — so the name never updates. Map it to `name` before
        # sending. An explicit `name` wins if both are supplied.
        if "displayName" in kwargs:
            display_name = kwargs.pop("displayName")
            kwargs.setdefault("name", display_name)

        try:
            response = self.session.put(f"/environments/{slug}", json=kwargs).json()

            # Handle new API response format: {success: true, data: {...}}
            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            # Handle legacy format (direct object)
            if isinstance(response, dict):
                return response

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Update environment request failed: {err}"
            ) from err

    def update_packages(self, slug: str, packages: list[str]) -> dict[str, Any]:
        """Update the package list for an environment.

        Updates the packages field in the environment's MongoDB document.
        This is typically called after installing or uninstalling packages in
        a local environment to keep the cloud metadata in sync.

        Args:
            slug: The slug of the environment to update.
            packages: List of package specifiers in "name==version" format.
                Example: ["numpy==1.24.0", "pandas==2.0.0"]

        Returns:
            Dictionary containing the updated environment data.

        Raises:
            ValueError: If the environment slug is invalid or packages list is empty.
            EnvironmentServiceRequestError: If the update request fails.

        Example:
            >>> client.update_packages("myenv_abc123", ["numpy==1.24.0", "requests==2.31.0"])
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        if not packages:
            raise ValueError("Packages list cannot be empty")

        try:
            response = self.session.post(
                "/environments/packages",
                json={"slug": slug, "packages": packages},
            ).json()

            # Handle new API response format: {success: true, data: {...}}
            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            # Handle legacy format (direct object)
            if isinstance(response, dict):
                return response

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(f"Update packages request failed: {err}") from err

    def get_pending_review_environments(
        self, page: Optional[int] = None, limit: Optional[int] = None
    ) -> dict[str, Any]:
        """Get list of environments pending admin review (Admin only).

        Returns environments with reviewStatus of REQUESTED or PENDING.
        This endpoint requires admin privileges.

        Args:
            page: Page number for pagination (default: 1)
            limit: Number of environments per page (default: 20)

        Returns:
            Dictionary containing:
                - environments: List of environment objects pending review
                - pagination: Pagination metadata

        Raises:
            EnvironmentServiceRequestError: If the request fails (e.g., not admin).

        Example:
            >>> result = client.get_pending_review_environments()
            >>> for env in result["environments"]:
            ...     print(f"{env['slug']}: {env['reviewStatus']}")
        """
        try:
            params = {}
            if page is not None:
                params["page"] = page
            if limit is not None:
                params["limit"] = limit

            response = self.session.get("/environments/pending-review", params=params).json()

            # Handle new API response format: {success: true, data: [...], meta: {...}}
            if isinstance(response, dict) and response.get("success") and "data" in response:
                return {
                    "environments": response["data"],
                    "pagination": response.get("meta", {}).get("pagination", {}),
                }

            # Handle legacy response formats for backward compatibility
            if isinstance(response, list):
                return {"environments": response}

            if isinstance(response, dict) and "environments" in response:
                return response

            # Fallback for unexpected response format
            return {"environments": []}
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Get pending review environments request failed: {err}"
            ) from err

    def confirm_upload(self, slug: str) -> dict[str, Any]:
        """Confirm that environment tarball was successfully uploaded to GCS.

        This should be called after upload_environment() completes. It verifies
        the tarball exists in GCS and updates the environment status to COMPLETE.

        Args:
            slug: The slug of the environment to confirm.

        Returns:
            Dictionary containing confirmation result:
                - slug: Environment slug
                - status: "COMPLETE" if successful
                - message: Confirmation message

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If confirmation fails (e.g., tarball not found).
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            response = self.session.post(f"/environments/{slug}/confirm-upload").json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            if isinstance(response, dict):
                return response

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Confirm upload failed for '{slug}': {err}"
            ) from err

    def share_environment(
        self, slug: str, target_type: str, email: str, permissions: list[str]
    ) -> dict[str, Any]:
        """Share environment with a user or organization.

        Args:
            slug: The slug of the environment to share.
            target_type: Type of target - 'user' or 'organization'.
            email: Email address of the user or organization to share with.
            permissions: List of permissions to grant. Valid values:
                - 'read': Can view the environment
                - 'write': Can modify the environment
                - 'execute': Can download/install the environment

        Returns:
            Dictionary containing the share result with granted permissions.

        Raises:
            ValueError: If the environment slug is invalid or permissions are invalid.
            EnvironmentServiceRequestError: If the share request fails.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        valid_permissions = {"read", "write", "execute"}
        invalid = set(permissions) - valid_permissions
        if invalid:
            raise ValueError(f"Invalid permissions: {invalid}. Valid: {valid_permissions}")

        if target_type not in ("user", "organization"):
            raise ValueError(
                f"Invalid target_type: {target_type}. Must be 'user' or 'organization'"
            )

        try:
            response = self.session.post(
                f"/environments/{slug}/share",
                json={
                    "targetType": target_type,
                    "email": email,
                    "permissions": permissions,
                },
            ).json()

            # Handle new API response format: {success: true, data: {...}}
            if isinstance(response, dict) and response.get("success") and "data" in response:
                result = response["data"]
            elif isinstance(response, dict):
                result = response
            else:
                raise EnvironmentServiceRequestError(
                    f"Unexpected response format from API: {response}"
                )

            # Update local registry with read_access_users if read permission granted
            if "read" in permissions and target_type == "user":
                registry_mgr = EnvironmentRegistryManager()
                found = registry_mgr.find_by_slug(slug)
                if found:
                    env_id, entry = found
                    current_users = entry.read_access_users or []
                    if email not in current_users:
                        updated_users = current_users + [email]
                        registry_mgr.update_environment(env_id, read_access_users=updated_users)
                        logger.debug("Added %s to read_access_users for %s", email, slug)

            return result
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Share environment request failed: {err}"
            ) from err

    def revoke_environment_access(
        self, slug: str, target_type: str, email: str, permissions: list[str]
    ) -> dict[str, Any]:
        """Revoke environment access from a user or organization.

        Args:
            slug: The slug of the environment.
            target_type: Type of target - 'user' or 'organization'.
            email: Email address of the user or organization to revoke access from.
            permissions: List of permissions to revoke.

        Returns:
            Dictionary containing the revoke result.

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the revoke request fails.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        if target_type not in ("user", "organization"):
            raise ValueError(
                f"Invalid target_type: {target_type}. Must be 'user' or 'organization'"
            )

        try:
            response = self.session.delete(
                f"/environments/{slug}/share",
                json={
                    "targetType": target_type,
                    "email": email,
                    "permissions": permissions,
                },
            ).json()

            # Handle new API response format: {success: true, data: {...}}
            if isinstance(response, dict) and response.get("success") and "data" in response:
                result = response["data"]
            elif isinstance(response, dict):
                result = response
            else:
                raise EnvironmentServiceRequestError(
                    f"Unexpected response format from API: {response}"
                )

            # Update registry: remove email from read_access_users if read permission was revoked
            if "read" in permissions and target_type == "user":
                try:
                    registry_mgr = EnvironmentRegistryManager()
                    found = registry_mgr.find_by_slug(slug)
                    if found:
                        env_id, entry = found
                        current_users = entry.read_access_users or []
                        if email in current_users:
                            updated_users = [u for u in current_users if u != email]
                            registry_mgr.update_environment(
                                env_id, read_access_users=updated_users if updated_users else None
                            )
                except (OSError, ValueError, EnvironmentNotFoundError) as registry_err:
                    logger.debug("Failed to update registry read_access_users: %s", registry_err)

            return result
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Revoke environment access request failed: {err}"
            ) from err

