    # =========================================================================
    # Share-by-Code Methods
    # Generate shareable codes that others can redeem to gain read access
    # =========================================================================

    def generate_share_code(self, slug: str) -> dict[str, Any]:
        """Generate a shareable code for an environment.

        Creates an 8-character uppercase alphanumeric code that others can
        redeem to gain read access to the environment. Only the owner can
        generate codes. Calling this again regenerates the code (invalidates
        the previous code). One code per environment at a time.

        Args:
            slug: The slug of the environment to generate a share code for.

        Returns:
            Dictionary containing:
                - code: The 8-character share code
                - slug: The environment slug

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the request fails (not owner,
                environment not found, etc.).

        Example:
            >>> client = EnvironmentManagerClient()
            >>> result = client.generate_share_code("my_env_abc123")
            >>> print(f"Share this code: {result['code']}")
            Share this code: ABC12XYZ
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            response = self.session.post(f"/environments/{slug}/share-code").json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                result = response["data"]
            elif isinstance(response, dict):
                result = response
            else:
                raise EnvironmentServiceRequestError(
                    f"Unexpected response format from API: {response}"
                )

            # Update local registry with the new access_key
            access_key = result.get("code") or result.get("accessKey")
            if access_key:
                registry_mgr = EnvironmentRegistryManager()
                found = registry_mgr.find_by_slug(slug)
                if found:
                    env_id, _ = found
                    registry_mgr.update_environment(env_id, access_key=access_key)
                    logger.debug("Updated registry access_key for %s", slug)

            return result
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Generate share code request failed: {err}"
            ) from err

    def delete_share_code(self, slug: str) -> dict[str, Any]:
        """Delete the share code for an environment.

        Removes the share code, preventing new redemptions. Users who have
        already redeemed the code keep their access. Only the owner can
        delete the share code.

        Args:
            slug: The slug of the environment.

        Returns:
            Dictionary containing success message.

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the request fails (not owner,
                environment not found, etc.).

        Example:
            >>> client = EnvironmentManagerClient()
            >>> client.delete_share_code("my_env_abc123")
            {'message': 'Share code removed'}
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            response = self.session.delete(f"/environments/{slug}/share-code").json()

            if isinstance(response, dict) and response.get("success"):
                result = response.get(
                    "data", {"message": response.get("message", "Share code removed")}
                )
            elif isinstance(response, dict):
                result = response
            else:
                raise EnvironmentServiceRequestError(
                    f"Unexpected response format from API: {response}"
                )

            # Update registry: clear access_key since share code was deleted
            try:
                registry_mgr = EnvironmentRegistryManager()
                found = registry_mgr.find_by_slug(slug)
                if found:
                    env_id, _ = found
                    registry_mgr.update_environment(env_id, access_key=None)
            except (OSError, ValueError, EnvironmentNotFoundError) as registry_err:
                logger.debug("Failed to clear registry access_key: %s", registry_err)

            return result
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Delete share code request failed: {err}"
            ) from err

    def redeem_share_code(self, code: str) -> dict[str, Any]:
        """Redeem a share code to gain read access to an environment.

        Redeems a share code to gain read access to the associated environment.
        The code is case-insensitive. Safe to call multiple times (idempotent).

        Args:
            code: The share code to redeem (8-character alphanumeric).

        Returns:
            Dictionary containing:
                - slug: Environment slug
                - name: Environment name
                - alreadyHadAccess: True if user already had access

        Raises:
            ValueError: If the code format is invalid.
            EnvironmentServiceRequestError: If the request fails (invalid code,
                user is already owner, etc.).

        Example:
            >>> client = EnvironmentManagerClient()
            >>> result = client.redeem_share_code("ABC12XYZ")
            >>> print(f"Access granted to: {result['name']}")
            Access granted to: My Environment
        """
        # Basic validation - code should be alphanumeric
        if not code or not code.strip():
            raise ValueError("Share code cannot be empty")

        code = code.strip().upper()
        if not code.isalnum():
            raise ValueError("Share code must be alphanumeric")

        try:
            response = self.session.post(
                "/environments/redeem-code",
                json={"code": code},
            ).json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            if isinstance(response, dict):
                return response

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Redeem share code request failed: {err}"
            ) from err

    # =========================================================================
    # Publishing Workflow Methods
    # State machine: NONE → REQUESTED → PENDING → APPROVED (or DENIED)
    # =========================================================================

    def request_publish(self, slug: str) -> dict[str, Any]:
        """Request to publish an environment to the public catalog.

        This initiates the publishing workflow. The environment owner submits
        a request which then goes through admin review before being made public.

        Args:
            slug: The slug of the environment to request publishing for.

        Returns:
            Dictionary containing the request result with updated environment data.

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the request fails (e.g., already
                requested, not owner, environment not found).

        Note:
            - Only the environment owner can request publishing.
            - Cannot request if status is already REQUESTED, PENDING, or APPROVED.
            - Triggers email notification to platform admins.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            response = self.session.post(
                "/environments/request-publish",
                json={"slug": slug},
            ).json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            if isinstance(response, dict):
                return response

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Request publish failed for '{slug}': {err}"
            ) from err

    def revoke_publish_request(self, slug: str) -> dict[str, Any]:
        """Revoke/cancel a pending publish request.

        Allows the owner to cancel their publish request before it's approved.
        Resets the review status back to NONE.

        Args:
            slug: The slug of the environment to revoke the publish request for.

        Returns:
            Dictionary containing the revoke result with updated environment data.

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If the request fails (e.g., not owner,
                no pending request, environment not found).

        Note:
            - Only the environment owner can revoke the request.
            - Valid only when status is REQUESTED, PENDING, or DENIED.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            response = self.session.put(
                "/environments/publish/revoke",
                json={"slug": slug},
            ).json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            if isinstance(response, dict):
                return response

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Revoke publish request failed for '{slug}': {err}"
            ) from err

    def get_publish_status(self, slug: str) -> str:
        """Get the current publishing status of an environment.

        Args:
            slug: The slug of the environment.

        Returns:
            The review status string: "none", "requested", "pending",
            "approved", or "denied".

        Raises:
            ValueError: If the environment slug is invalid.
            EnvironmentServiceRequestError: If fetching the environment fails.
        """
        if not is_valid_slug(slug):
            raise ValueError(f"Invalid environment slug: {slug}")

        try:
            env_data = self.get_environment_by_slug(slug)
            return env_data.get("reviewStatus", "none")
        except EnvironmentServiceRequestError:
            raise
        except Exception as err:
            raise EnvironmentServiceRequestError(
                f"Failed to get publish status for '{slug}': {err}"
            ) from err

