    def create_environment_group(
        self,
        display_name: str,
        description: Optional[str] = None,
        tags: Optional[list[str]] = None,
        category: Optional[str] = None,
        visibility: Optional[str] = None,
        environments: Optional[list[str]] = None,
        latest_env: Optional[str] = None,
        inherit_image: Optional[bool] = None,
        light_logo: Optional[Path] = None,
        dark_logo: Optional[Path] = None,
    ) -> dict[str, Any]:
        """Create a new environment group.

        Requires platform_admin role.

        Args:
            display_name: Display name for the group (1-100 chars, required)
            description: Group description (max 500 chars)
            tags: List of tags for the group
            category: Group category ("package" or "subject-matter")
            visibility: Visibility setting ("private" or "public")
            environments: List of environment slugs to include in the group
            latest_env: Environment slug to set as the "current" version.
                Must be in environments if both are provided.
            inherit_image: If True, copy logos from latest_env. Requires latest_env.
            light_logo: Path to light theme logo image file
            dark_logo: Path to dark theme logo image file

        Returns:
            Dictionary containing the created environment group data.

        Raises:
            EnvironmentValidationError: If display_name is invalid or missing.
            EnvironmentServiceRequestError: If the request fails or user lacks permission.
        """
        if not display_name or not display_name.strip():
            raise EnvironmentValidationError("display_name is required")

        if len(display_name) > 100:
            raise EnvironmentValidationError("display_name must be 100 characters or less")

        if description and len(description) > 500:
            raise EnvironmentValidationError("description must be 500 characters or less")

        if category and category not in ("package", "subject-matter"):
            raise EnvironmentValidationError("category must be 'package' or 'subject-matter'")

        if visibility and visibility not in ("private", "public"):
            raise EnvironmentValidationError("visibility must be 'private' or 'public'")

        if inherit_image and not latest_env:
            raise EnvironmentValidationError("inherit_image requires latest_env to be set")

        if latest_env and environments and latest_env not in environments:
            raise EnvironmentValidationError("latest_env must be in environments list")

        try:
            # Build multipart form data
            data: dict[str, Any] = {"displayName": display_name}

            if description is not None:
                data["description"] = description
            if tags is not None:
                data["tags"] = ",".join(tags) if tags else ""
            if category is not None:
                data["category"] = category
            if visibility is not None:
                data["visibility"] = visibility
            if environments is not None:
                data["environments"] = ",".join(environments) if environments else ""
            if latest_env is not None:
                data["latestEnv"] = latest_env
            if inherit_image is not None:
                data["inheritImage"] = str(inherit_image).lower()

            # Handle file uploads
            files = {}
            file_handles = []
            try:
                if light_logo:
                    light_handle = open(light_logo, "rb")  # pylint: disable=consider-using-with
                    file_handles.append(light_handle)
                    files["lightLogo"] = (light_logo.name, light_handle, "image/png")
                if dark_logo:
                    dark_handle = open(dark_logo, "rb")  # pylint: disable=consider-using-with
                    file_handles.append(dark_handle)
                    files["darkLogo"] = (dark_logo.name, dark_handle, "image/png")

                if files:
                    response = self.session.post(
                        "/environment-groups", data=data, files=files
                    ).json()
                else:
                    response = self.session.post("/environment-groups", data=data).json()
            finally:
                for handle in file_handles:
                    handle.close()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Create environment group request failed: {err}"
            ) from err

    def update_environment_group(
        self,
        group_slug: str,
        display_name: Optional[str] = None,
        description: Optional[str] = None,
        tags: Optional[list[str]] = None,
        category: Optional[str] = None,
        visibility: Optional[str] = None,
        environments: Optional[list[str]] = None,
        add_envs: Optional[list[str]] = None,
        remove_envs: Optional[list[str]] = None,
        latest_env: Optional[str] = None,
        inherit_image: Optional[bool] = None,
    ) -> dict[str, Any]:
        """Update an existing environment group.

        Requires platform_admin role.

        Args:
            group_slug: The slug of the environment group to update
            display_name: New display name (1-100 chars)
            description: New description (max 500 chars)
            tags: New list of tags (replaces existing)
            category: New category ("package" or "subject-matter")
            visibility: New visibility ("private" or "public")
            environments: Full replacement of environment list (slugs).
                Cannot be used with add_envs/remove_envs.
            add_envs: Environment slugs to add to the group (delta update).
                Cannot be used with environments.
            remove_envs: Environment slugs to remove from the group (delta update).
                Cannot be used with environments. Cannot remove latest_env.
            latest_env: Set the "current version" environment slug
            inherit_image: If True, copy logos from latest_env

        Returns:
            Dictionary containing the updated environment group data.

        Raises:
            EnvironmentValidationError: If arguments are invalid.
            EnvironmentServiceRequestError: If the request fails or user lacks permission.
        """
        if not group_slug:
            raise EnvironmentValidationError("group_slug is required")

        if display_name is not None and len(display_name) > 100:
            raise EnvironmentValidationError("display_name must be 100 characters or less")

        if description is not None and len(description) > 500:
            raise EnvironmentValidationError("description must be 500 characters or less")

        if category is not None and category not in ("package", "subject-matter"):
            raise EnvironmentValidationError("category must be 'package' or 'subject-matter'")

        if visibility is not None and visibility not in ("private", "public"):
            raise EnvironmentValidationError("visibility must be 'private' or 'public'")

        # Validate mutually exclusive options
        if environments is not None and (add_envs is not None or remove_envs is not None):
            raise EnvironmentValidationError(
                "Cannot use 'environments' with 'add_envs' or 'remove_envs'. "
                "Use either full replacement OR delta updates."
            )

        if add_envs and remove_envs:
            overlap = set(add_envs) & set(remove_envs)
            if overlap:
                raise EnvironmentValidationError(
                    f"Cannot add and remove the same environment slugs: {overlap}"
                )

        if latest_env and environments and latest_env not in environments:
            raise EnvironmentValidationError("latest_env must be in environments list")

        try:
            # Build JSON body
            body: dict[str, Any] = {}

            if display_name is not None:
                body["displayName"] = display_name
            if description is not None:
                body["description"] = description
            if tags is not None:
                body["tags"] = tags
            if category is not None:
                body["category"] = category
            if visibility is not None:
                body["visibility"] = visibility
            if environments is not None:
                body["environments"] = environments
            if add_envs is not None:
                body["addEnvs"] = add_envs
            if remove_envs is not None:
                body["removeEnvs"] = remove_envs
            if latest_env is not None:
                body["latestEnv"] = latest_env
            if inherit_image is not None:
                body["inheritImage"] = inherit_image

            response = self.session.put(f"/environment-groups/{group_slug}", json=body).json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Update environment group request failed: {err}"
            ) from err

    def delete_environment_group(self, group_slug: str) -> dict[str, Any]:
        """Delete an environment group.

        Requires platform_admin role.

        Args:
            group_slug: The slug of the environment group to delete

        Returns:
            Dictionary containing the deletion confirmation message.

        Raises:
            EnvironmentValidationError: If group_slug is invalid.
            EnvironmentServiceRequestError: If the request fails or user lacks permission.
        """
        if not group_slug:
            raise EnvironmentValidationError("group_slug is required")

        try:
            response = self.session.delete(f"/environment-groups/{group_slug}").json()

            if isinstance(response, dict) and response.get("success") and "data" in response:
                return response["data"]

            # Handle direct success response
            if isinstance(response, dict) and response.get("success"):
                return {"message": "Environment group deleted successfully"}

            raise EnvironmentServiceRequestError(f"Unexpected response format from API: {response}")
        except RequestsApiError as err:
            raise EnvironmentServiceRequestError(
                f"Delete environment group request failed: {err}"
            ) from err

    def _post_execute(self, slug: str, body: Optional[dict[str, str]]) -> Optional[str]:
        """POST /environments/{slug}/execute and return the signed downloadUrl.

        Handles both the new ``{success, data}`` envelope and the legacy bare
        response shape. ``body`` is ``{"uri": <mirror>}`` for mirror requests or
        ``None`` for canonical (which sends no body).
        """
        resp = self.session.post(f"/environments/{slug}/execute", json=body).json()
        if isinstance(resp, dict) and resp.get("success") and "data" in resp:
            data = resp["data"]
        else:
            data = resp
        return (data or {}).get("downloadUrl") if isinstance(data, dict) else None

    # pylint: disable-next=too-many-branches,too-many-statements,too-many-locals
    async def install_environment_from_storage(
        self,
        slug: str,
        target_dir: str,
        temp: bool = False,
        overwrite: bool = False,
        progress_callback: Optional[Callable[[str, int, int], None]] = None,
        auto_add_kernels: bool = False,
        auto_install_python: bool = False,
        env_info: Optional[dict[str, Any]] = None,
    ) -> dict[str, Any]:
        """Install environment from cloud storage (signed URL).

        Gets a signed download URL from the API and downloads/installs the environment.
        The URL points at either the canonical GCS tarball or a same-cloud mirror
        (Azure Blob) selected by :func:`_pick_mirror_uri` based on ``QBRAID_CLOUD``.

        Args:
            slug: Environment slug to install
            target_dir: Target directory for installation
            temp: If True, install as temporary (non-persistent)
            overwrite: If True, overwrite existing environment without prompting
            progress_callback: Optional callback function(stage, completed, total)
                for progress reporting (download/extract).
            auto_add_kernels: If True, add the kernel to the Jupyter's global kernel registry
            auto_install_python: If True and required Python version is not found,
                attempt to install it via uv (if available)
            env_info: Optional pre-fetched environment metadata (as returned by
                ``get_environment_by_slug``). Callers that already fetched it (e.g.
                the CLI preflight path) can pass it through to skip a round-trip.

        Returns:
            Dictionary with installation status and metadata including:
                - status: "success"
                - env_id: Environment ID
                - slug: Environment slug
                - target_dir: Installation path
                - temp: Whether temporary
                - warnings: List of warning messages (platform, python, etc.)

        Raises:
            EnvironmentValidationError: If installation arguments are invalid
            EnvironmentDownloadError: If getting download URL or downloading fails
            EnvironmentExtractionError: If extraction fails
            EnvironmentInstallError: If relocation or registration fails
        """
        # Fetch env metadata FIRST — we need envMirrors for mirror selection, and
        # downstream code (platform check, name lookup) reuses this dict.
        if env_info is None:
            try:
                env_data = self.get_environment_by_slug(slug)
            except EnvironmentServiceRequestError as err:
                raise EnvironmentServiceRequestError(
                    f"Failed to fetch environment data for '{slug}': {err}"
                ) from err
            except Exception as err:
                raise EnvironmentValidationError(f"Environment '{slug}' not found: {err}") from err
        else:
            # Callers pass env_info to skip the internal fetch; validate the shape
            # so a wrong type (Pydantic model, list, str) doesn't AttributeError
            # midway through the install flow.
            if not isinstance(env_info, dict):
                raise EnvironmentValidationError(
                    f"env_info must be a dict, got {type(env_info).__name__}"
                )
            env_data = env_info

        # Pick a mirror URI matching QBRAID_CLOUD, or None to request canonical.
        # We send an empty body for canonical so old API deployments (pre-mirror)
        # continue to work — they ignore the missing field and sign envS3Url.
        picked_uri = _pick_mirror_uri(env_data.get("envMirrors"))
        exec_body: Optional[dict[str, str]] = {"uri": picked_uri} if picked_uri else None

        try:
            storage_url = self._post_execute(slug, exec_body)
        except RequestsApiError as err:
            # Retry canonical on the URI-specific rejection codes: 400 (unknown),
            # 404 (mirror removed between GET and POST), 422 (validation). 401/403
            # are auth failures — canonical would fail identically, so let them
            # bubble. 5xx also bubbles (server broken, not URI-specific).
            cause = getattr(err, "__cause__", None)
            http_resp = getattr(cause, "response", None)
            status = getattr(http_resp, "status_code", None) if http_resp is not None else None
            if status in {400, 404, 422} and picked_uri:
                logger.info(
                    "Mirror URI rejected (status=%s) for '%s'; retrying with canonical.",
                    status,
                    slug,
                )
                try:
                    storage_url = self._post_execute(slug, None)
                    picked_uri = None  # so the logger line below reflects reality
                except RequestsApiError as retry_err:
                    raise EnvironmentDownloadError(
                        f"Failed to get download URL for environment '{slug}': {retry_err}"
                    ) from retry_err
            else:
                raise EnvironmentDownloadError(
                    f"Failed to get download URL for environment '{slug}': {err}"
                ) from err

        if not storage_url:
            raise EnvironmentDownloadError(f"Download URL not found in API response for '{slug}'")

        # Structured line so ops can see mirror-vs-canonical split without
        # instrumenting the API. Only host is logged, never the signed URL.
        from urllib.parse import urlparse  # pylint: disable=import-outside-toplevel

        served_host = urlparse(storage_url).hostname or "?"
        logger.info(
            "Env '%s' download served via %s (host=%s)",
            slug,
            "mirror" if picked_uri else "canonical",
            served_host,
        )

        # Platform compatibility validation (warn but don't block)
        env_platform = env_data.get("platform")
        current_platform = get_current_platform()
        platform_result = validate_platform_compatibility(env_platform, current_platform)

        if platform_result.compatibility != PlatformCompatibility.COMPATIBLE:
            logger.warning(
                "Platform compatibility warning for '%s': %s",
                slug,
                platform_result.message,
            )
            # Log but don't raise - design decision is to warn only
            if platform_result.compatibility == PlatformCompatibility.INCOMPATIBLE:
                logger.warning(
                    "Environment was built for %s but current platform is %s. "
                    "Proceeding anyway as per design decision to warn-only.",
                    env_platform,
                    current_platform,
                )

        # Generate a unique env_id for this installation
        # Using env_id as directory name allows multiple installations of the same slug
        registry_mgr = EnvironmentRegistryManager()
        env_id = registry_mgr._generate_unique_env_id()  # pylint: disable=protected-access

        # Use name prefix + env_id as directory name for discoverability
        from .paths import make_env_dir_name  # pylint: disable=import-outside-toplevel

        env_name = env_data.get("name", slug)
        final_target = Path(target_dir) / make_env_dir_name(env_name, env_id)

        # Check if this slug is already installed (warn but allow duplicate installations)
        existing_by_slug = registry_mgr.find_by_slug(slug)
        if existing_by_slug and not overwrite:
            existing_env_id, existing_entry = existing_by_slug
            logger.info(
                "Environment with slug '%s' already installed (env_id: %s) at %s. "
                "Installing as new instance with env_id: %s",
                slug,
                existing_env_id,
                existing_entry.path,
                env_id,
            )

        # Handle edge case where generated env_id directory already exists (shouldn't happen)
        if final_target.exists():
            shutil.rmtree(final_target)

        try:
            # Download using requests with progress callback support
            def _download_file() -> str:
                """Download file synchronously using requests."""
                try:
                    # 15 min: Azure Blob large-object GET has a longer tail than
                    # GCS; 10 min was cutting it close on ~10 GB CUDA envs.
                    response = self.session.get(storage_url, stream=True, timeout=900)
                    response.raise_for_status()
                except RequestsApiError as err:
                    raise EnvironmentDownloadError(
                        f"Failed to download environment archive from {storage_url}: {err}"
                    ) from err

                # Get total size if available
                total_size = int(response.headers.get("content-length", 0))

                with tempfile.NamedTemporaryFile(suffix=".tar.zst", delete=False) as temp_file:
                    bytes_downloaded = 0
                    chunk_size = 8192

                    for chunk in response.iter_content(chunk_size=chunk_size):
                        if chunk:
                            temp_file.write(chunk)
                            bytes_downloaded += len(chunk)
                            if progress_callback:
                                progress_callback("download", bytes_downloaded, total_size)

                    return temp_file.name

            # Run download in thread pool to avoid blocking event loop
            temp_file_path = await asyncio.to_thread(_download_file)

            # Ensure parent directory exists
            final_target.parent.mkdir(parents=True, exist_ok=True)

            # Extract to unique temp directory then move to final target
            # This avoids race conditions when multiple environments are installed in parallel
            # IMPORTANT: Use temp dir on SAME filesystem as target so move is atomic (rename)
            # Using /tmp would cause cross-filesystem copy which isn't atomic
            def _extract_directly() -> None:
                """Extract to temp directory then move to target."""
                with tempfile.TemporaryDirectory(dir=final_target.parent) as temp_extract_dir:
                    extracted_dir = self._extract_zstd_tar(
                        Path(temp_file_path),
                        Path(temp_extract_dir),
                        progress_callback,
                    )
                    # Create marker file BEFORE moving so it exists when directory
                    # appears at final location - prevents sync race condition
                    (extracted_dir / ".qbraid_installing").touch()
                    # Move extracted directory to final target (atomic on same filesystem)
                    if final_target.exists():
                        shutil.rmtree(final_target)
                    shutil.move(str(extracted_dir), str(final_target))

            await asyncio.to_thread(_extract_directly)

            # Verify extraction was successful
            if not final_target.exists():
                raise EnvironmentInstallError(
                    f"Environment directory {final_target} not found after extraction"
                )

            # Fix hardcoded paths for relocation
            await self._relocate_environment_paths(final_target)

            # Auto-repair venv if needed (design decision: auto-repair on download)
            # This fixes any remaining broken symlinks or paths after relocation
            try:
                repair_success, repair_actions = await asyncio.to_thread(
                    repair_venv, final_target, auto_install_python=False
                )
                if repair_actions:
                    logger.info("Venv repair actions for %s: %s", slug, repair_actions)
                if not repair_success:
                    logger.warning("Venv repair incomplete for %s, some issues may remain", slug)
            except Exception as repair_err:  # pylint: disable=broad-exception-caught
                # Log but don't fail - repair is best-effort
                logger.warning("Venv repair failed for %s: %s", slug, repair_err)

            # Rename kernel directories to use env_id suffix
            # Downloaded environments have kernels named like python3_<slug>
            # We rename them to python3_<env_id> for uniqueness
            kernels_dir = final_target / "kernels"
            if kernels_dir.is_dir():
                for kernel_dir in list(kernels_dir.iterdir()):
                    if kernel_dir.is_dir():
                        # Rename kernel directory to use env_id
                        new_kernel_name = f"python3_{env_id}"
                        new_kernel_dir = kernels_dir / new_kernel_name
                        if kernel_dir.name != new_kernel_name:
                            kernel_dir.rename(new_kernel_dir)
                            logger.debug(
                                "Renamed kernel directory %s -> %s",
                                kernel_dir.name,
                                new_kernel_name,
                            )

                        # Update kernel.json to use correct python path
                        kernel_json_path = new_kernel_dir / "kernel.json"
                        if kernel_json_path.exists():
                            try:
                                with open(kernel_json_path, "r", encoding="utf-8") as f:
                                    kernel_spec = json.load(f)

                                # Update the python executable path
                                # The tarball has paths like /.../slug/pyenv/bin/python
                                # We need to update to /.../env_id/pyenv/bin/python
                                if "argv" in kernel_spec and kernel_spec["argv"]:
                                    old_path = kernel_spec["argv"][0]
                                    new_python_path = str(final_target / "pyenv" / "bin" / "python")
                                    if old_path != new_python_path:
                                        kernel_spec["argv"][0] = new_python_path
                                        with open(kernel_json_path, "w", encoding="utf-8") as f:
                                            json.dump(kernel_spec, f, indent=1)
                                        logger.debug(
                                            "Updated kernel.json python path: %s -> %s",
                                            old_path,
                                            new_python_path,
                                        )
                            except (json.JSONDecodeError, OSError) as e:
                                logger.warning(
                                    "Failed to update kernel.json at %s: %s",
                                    kernel_json_path,
                                    e,
                                )

            # Register environment in registry
            # Convert API response to EnvironmentConfig if needed
            try:
                # Create EnvironmentConfig from API data
                # Map API response fields to EnvironmentConfig
                # Convert packages list ['pkg==ver', ...] to dict {'pkg': 'ver', ...}
                packages_list = env_data.get("packages") or env_data.get("packagesInImage") or []
                python_packages = None
                if packages_list:
                    python_packages = {}
                    for pkg in packages_list:
                        if "==" in pkg:
                            name, version = pkg.split("==", 1)
                            python_packages[name] = version
                        else:
                            python_packages[pkg] = ""

                # Auto-discover metadata from extracted environment if API doesn't provide it
                discovered_kernel_name = None
                discovered_python_version = None

                # Look for kernel.json in kernels directory
                kernels_dir = final_target / "kernels"
                if kernels_dir.is_dir():
                    for kernel_dir in kernels_dir.iterdir():
                        if kernel_dir.is_dir():
                            kernel_json = kernel_dir / "kernel.json"
                            if kernel_json.exists() and not discovered_kernel_name:
                                try:
                                    with kernel_json.open(encoding="utf-8") as f:
                                        kernel_data = json.load(f)
                                        discovered_kernel_name = kernel_data.get("display_name")
                                except (json.JSONDecodeError, IOError):
                                    pass

                # Try to get python version from pyenv
                pyenv_python = final_target / "pyenv" / "bin" / "python"
                if pyenv_python.exists() and not discovered_python_version:
                    try:
                        result = subprocess.run(
                            [str(pyenv_python), "--version"],
                            capture_output=True,
                            text=True,
                            check=False,
                        )
                        if result.returncode == 0:
                            version_output = result.stdout.strip()
                            if version_output.startswith("Python "):
                                discovered_python_version = version_output[7:]
                            else:
                                discovered_python_version = version_output
                    except Exception:  # pylint: disable=broad-exception-caught
                        pass

                # Fallback: read from pyvenv.cfg if execution failed (e.g., Linux binary on macOS)
                if not discovered_python_version:
                    from .python import extract_version_from_pyvenv_cfg

                    pyvenv_cfg = final_target / "pyenv" / "pyvenv.cfg"
                    discovered_python_version = extract_version_from_pyvenv_cfg(pyvenv_cfg)

                # Get logo URLs from API response
                api_logo_url = env_data.get(
                    "logo"
                )  # {"light": "https://...", "dark": "https://..."}

                # Download kernel logo from URL if available
                if api_logo_url and kernels_dir.is_dir():
                    from .kernels import download_kernel_logo

                    kernel_logo_src = api_logo_url.get("light") or api_logo_url.get("dark")
                    if kernel_logo_src:
                        for kdir in kernels_dir.iterdir():
                            if kdir.is_dir():
                                download_kernel_logo(kernel_logo_src, kdir)
                                break

                # Don't pass python_packages to EnvironmentConfig (has PyPI validator)
                # Pass it directly to register_environment instead
                env_config = EnvironmentConfig(
                    name=env_data.get("name", extract_alias_from_path(final_target)),
                    description=env_data.get("description"),
                    tags=env_data.get("tags"),
                    python_version=env_data.get("pythonVersion") or discovered_python_version,
                    kernel_name=env_data.get("kernelName") or discovered_kernel_name,
                    shell_prompt=env_data.get("shellPrompt"),
                    visibility=env_data.get("visibility", "private"),
                )

                # Register with pre-generated env_id (directory already uses this env_id)
                registry_mgr.register_environment(
                    path=final_target,
                    env_type="temporary" if temp else "qbraid-managed",
                    env_id=env_id,
                    slug=slug,
                    owner=env_data.get("owner"),
                    config=env_config,
                    is_temporary=temp,
                    python_packages=python_packages,
                    logo_url=api_logo_url,
                    groups=[
                        g["slug"] if isinstance(g, dict) else g
                        for g in (env_data.get("groups") or [])
                    ]
                    or None,
                )
                logger.info(
                    "Registered environment in registry: %s (env_id: %s, slug: %s)",
                    env_config.name,
                    env_id,
                    slug,
                )

                # Update registry with local packages only (not inherited from system site-packages)
                # This overwrites the API's packages with only locally installed packages
                _update_registry_packages(env_id)

                # Install kernel into Jupyter's global kernel registry
                # This makes the kernel visible to Jupyter (jupyter kernelspec list)
                if auto_add_kernels:
                    add_kernels(env_id)
                    logger.info(
                        "Installed kernel for environment: %s (env_id: %s, slug: %s)",
                        env_config.name,
                        env_id,
                        slug,
                    )

            except Exception as reg_err:
                raise EnvironmentRegistryError(
                    f"Failed to register environment '{slug}' in registry: {reg_err}"
                ) from reg_err

            # Remove installation marker - environment is now fully set up
            install_marker = final_target / ".qbraid_installing"
            install_marker.unlink(missing_ok=True)

            # Clean up temp file
            Path(temp_file_path).unlink(missing_ok=True)

            # Post-download validation and warnings
            warnings = []

            # Re-check platform compatibility (post-download warning)
            if platform_result.compatibility != PlatformCompatibility.COMPATIBLE:
                warnings.append(
                    f"Platform warning: Environment was built for {env_platform} "
                    f"but current platform is {current_platform}. "
                    "The environment may not work correctly."
                )

            # Check Python availability
            # Use API pythonVersion if available, otherwise fall back to
            # discovered version from pyvenv.cfg
            required_python = env_config.python_version or discovered_python_version
            if required_python:
                # Normalize to major.minor (e.g., "3.11.9" -> "3.11")
                parts = required_python.split(".")
                if len(parts) >= 2:
                    required_python = f"{parts[0]}.{parts[1]}"
                from .python import find_python, install_python, is_uv_available

                python_info = find_python(required_python)
                if python_info is None:
                    if auto_install_python and is_uv_available():
                        try:
                            install_python(required_python)
                            logger.info("Installed Python %s via uv", required_python)
                        except Exception as install_err:
                            warnings.append(
                                f"Python {required_python} not found and "
                                f"auto-install failed: {install_err}. "
                                f"Run 'uv python install {required_python}'"
                                f" or install manually, then run "
                                f"'qbraid envs repair {env_id}'."
                            )
                    else:
                        install_hint = (
                            f"Run 'uv python install {required_python}' or "
                            if is_uv_available()
                            else ""
                        )
                        warnings.append(
                            f"Python {required_python} not found on system. "
                            f"{install_hint}install Python {required_python} manually, "
                            f"then run 'qbraid envs repair {env_id}' to fix symlinks."
                        )

            # Log warnings
            for warning in warnings:
                logger.warning(warning)

            return {
                "status": "success",
                "env_id": env_id,
                "slug": slug,
                "target_dir": str(final_target),
                "temp": temp,
                "warnings": warnings,
            }

        except EnvironmentOperationError:
            raise
        except Exception as err:
            # Clean up on failure
            if "temp_file_path" in locals():
                Path(temp_file_path).unlink(missing_ok=True)
            if final_target.exists():
                shutil.rmtree(final_target, ignore_errors=True)

            raise EnvironmentInstallError(f"Environment installation failed: {err}") from err

    def create_similar_environment(
        self,
        env_info: dict[str, Any],
        target_dir: str,
        auto_add_kernels: bool = False,
        progress_callback: Optional[Callable[[str, int, int], None]] = None,
    ) -> dict[str, Any]:
        """Create a local environment with similar packages to a cloud environment.

        This is the fallback path when a cloud environment can't be downloaded
        directly (e.g. platform mismatch or missing Python version).  It creates
        a fresh venv on the current platform and pip-installs the package list
        from the cloud environment metadata.

        Args:
            env_info: Environment metadata dict from the API (as returned by
                ``get_environment_by_slug``).  Expected keys: ``name``,
                ``displayName``, ``slug``, ``description``, ``tags``,
                ``kernelName``, ``shellPrompt``, ``pythonVersion``,
                ``visibility``, ``packages``, ``packagesInImage``, ``logo``.
            target_dir: Parent directory for the new environment.
            auto_add_kernels: If True, register the kernel with Jupyter.
            progress_callback: Optional ``callback(stage, completed, total)``.

        Returns:
            Dict with ``env_id``, ``path``, ``packages_installed`` count, and
            ``warnings`` list.
        """
        from .create import create_local_venv, create_qbraid_env_assets
        from .packages import pip_install
        from .schema import EnvironmentConfig

        # Extract package list
        packages_list = env_info.get("packages") or env_info.get("packagesInImage") or []

        # Generate unique env_id and path
        env_id = generate_env_id()
        env_path = Path(target_dir) / env_id

        # Build config from cloud env metadata
        env_name = env_info.get("displayName") or env_info.get("name") or f"local_{env_id}"
        cloud_slug = env_info.get("slug")
        description = (
            env_info.get("description")
            or f"Local recreation of {cloud_slug or 'cloud environment'}"
        )

        env_config = EnvironmentConfig(
            name=env_name,
            description=description,
            tags=env_info.get("tags"),
            kernel_name=env_info.get("kernelName"),
            shell_prompt=env_info.get("shellPrompt"),
            python_version=env_info.get("pythonVersion"),
            visibility=env_info.get("visibility", "private"),
        )

        logo_url = env_info.get("logo")
        kernel_logo_url = None
        if logo_url:
            kernel_logo_url = logo_url.get("light") or logo_url.get("dark")

        # Owner (best-effort from session)
        owner = None
        try:
            user_data = self.session.get("/identity").json()
            data = user_data.get("data", user_data) if isinstance(user_data, dict) else {}
            if isinstance(data, dict) and data.get("username"):
                owner = {
                    "username": data["username"],
                    "email": data.get("email", ""),
                }
        except Exception:  # noqa: BLE001
            pass

        if progress_callback:
            progress_callback("create_assets", 0, 1)

        # Create qBraid assets (metadata, kernel files, registry entry)
        create_qbraid_env_assets(
            env_id,
            str(env_path),
            env_config,
            kernel_logo_url=kernel_logo_url,
            logo_url=logo_url,
            auto_add_kernels=auto_add_kernels,
            owner=owner,
        )

        if progress_callback:
            progress_callback("create_venv", 0, 1)

        # Create the virtual environment
        create_local_venv(
            env_path,
            env_config.shell_prompt or env_name,
            None,  # python_exe — use system default
            env_id,
        )

        if progress_callback:
            progress_callback("create_venv", 1, 1)

        # Install packages
        warnings: list[str] = []
        packages_installed = 0

        if packages_list:
            if progress_callback:
                progress_callback("pip_install", 0, len(packages_list))

            try:
                result = pip_install(env_id, packages_list)
                if result and result.get("success"):
                    packages_installed = len(packages_list)
                else:
                    packages_installed = len(packages_list)
                    output = (result or {}).get("output", "")
                    error_lines = [
                        line.strip()
                        for line in output.split("\n")
                        if "ERROR" in line or "Could not find" in line
                    ]
                    if error_lines:
                        warnings.append(
                            f"Some packages may have failed to install: "
                            f"{'; '.join(error_lines[:3])}"
                        )
            except Exception as err:  # noqa: BLE001
                logger.warning("pip install failed for %s: %s", env_id, err)
                warnings.append(f"Package installation failed: {err}")

            if progress_callback:
                progress_callback("pip_install", len(packages_list), len(packages_list))

        logger.info(
            "Created similar environment: env_id=%s, name=%s, packages=%d",
            env_id,
            env_name,
            packages_installed,
        )

        return {
            "env_id": env_id,
            "path": str(env_path),
            "packages_installed": packages_installed,
            "warnings": warnings,
        }

    async def upload_environment(
        self,
        identifier: str,
        slug: Optional[str] = None,
        group_slug: Optional[str] = None,
        overwrite: bool = False,
        progress_callback: Optional[Callable[[str, int, int], None]] = None,
    ) -> dict[str, Any]:
        """Upload local environment tarball to cloud storage (GCS).

        If slug is not provided, creates the environment in the API first to get
        a slug. Then prepares a copy with updated paths and uploads it to GCS.
        The environment will be private by default - use request_publish() to
        request public visibility.

        Args:
            identifier: Environment name (if unique) or env_id to upload
            slug: Optional existing slug. If provided, skips create_environment()
                and uploads directly to this slug. If None, creates a new
                environment entry first.
            group_slug: Optional environment group slug to add this environment to.
                If None and the local entry has groups, uses the first group.
            overwrite: If True, overwrite existing uploaded environment
            progress_callback: Optional callback function(stage, completed, total)
                for progress reporting (prepare/archive/upload).

        Returns:
            Dictionary with upload status and metadata including:
                - status: "success"
                - slug: The environment slug
                - env_id: Local environment ID
                - bucket: GCS bucket name
                - path: Path in bucket

        Raises:
            EnvironmentValidationError: If arguments are invalid
            EnvironmentServiceRequestError: If API request fails
            EnvironmentOperationError: If preparation, archiving or upload fails

        Example:
            # Create and upload in one call
            result = await client.upload_environment("my_env")

            # Or separate steps
            env_data = client.create_environment(config)
            result = await client.upload_environment("my_env", slug=env_data["slug"])
        """
        registry_mgr = EnvironmentRegistryManager()

        # Find environment in registry
        entry = None
        env_id = None

        found_by_name = registry_mgr.find_by_name(identifier)
        if found_by_name:
            env_id, entry = found_by_name
        else:
            found_by_id = registry_mgr.find_by_env_id(identifier)
            if found_by_id:
                env_id, entry = found_by_id
            else:
                raise EnvironmentValidationError(
                    f"Environment '{identifier}' not found. "
                    "Use name (if unique) or env_id to reference the environment."
                )

        env_path = entry.path

        # Validate environment path exists
        if not env_path.exists():
            raise EnvironmentValidationError(f"Environment path does not exist: {env_path}")

        if not env_path.is_dir():
            raise EnvironmentValidationError(f"Environment path is not a directory: {env_path}")

        if progress_callback:
            progress_callback("prepare", 0, 3)

        # Determine group_slug: explicit parameter > entry.groups[0] > None
        effective_group_slug = group_slug
        if effective_group_slug is None and entry.groups:
            effective_group_slug = entry.groups[0]

        # Step 1: Get or create slug
        if slug is None:
            # No slug provided - create environment in API first
            # Note: python_version will be sanitized by EnvironmentConfig validator
            # (strips "Python " prefix and whitespace)

            env_config = EnvironmentConfig(
                name=entry.name,
                description=entry.description,
                tags=entry.tags,
                python_version=entry.python_version,
                platform=entry.platform,
                kernel_name=entry.kernel_name,
                shell_prompt=entry.shell_prompt,
                python_packages=entry.python_packages,
                visibility=entry.visibility,
                group_slug=effective_group_slug,
            )

            # Pass logo URLs from registry entry
            upload_logo_light = None
            upload_logo_dark = None
            if entry.logo_url:
                upload_logo_light = entry.logo_url.get("light")
                upload_logo_dark = entry.logo_url.get("dark")

            try:
                env_data = self.create_environment(
                    env_config,
                    logo_light_url=upload_logo_light,
                    logo_dark_url=upload_logo_dark,
                )
                slug = env_data.get("slug")
                if not slug:
                    raise EnvironmentServiceRequestError(
                        "Create environment API did not return a slug"
                    )
                # Update local registry with the new slug
                registry_mgr.set_slug(env_id, slug)
                logger.info("Updated registry with slug '%s' for env_id '%s'", slug, env_id)
            except Exception as err:
                raise EnvironmentServiceRequestError(
                    f"Failed to create environment in API: {err}"
                ) from err
        else:
            # Slug provided - validate it exists
            if not is_valid_slug(slug):
                raise EnvironmentValidationError(f"Invalid slug format: {slug}")

        if progress_callback:
            progress_callback("prepare", 1, 3)

        # Step 2: Prepare environment copy with slug naming and updated paths
        with tempfile.TemporaryDirectory() as temp_dir:
            temp_dir_path = Path(temp_dir)
            slug_env_path = temp_dir_path / slug

            def _prepare_environment_copy() -> None:
                """Copy environment and update paths for .qbraid/environments.

                This function sanitizes all user-specific paths (like /Users/kanav or
                /home/username) to the generic /home/jovyan/.qbraid/environments/{slug}
                format used in qBraid Lab.
                """
                # Copy environment directory to temp location with slug name
                shutil.copytree(env_path, slug_env_path, symlinks=True, dirs_exist_ok=False)

                # Update paths in shebangs and activation scripts
                pyenv_path = slug_env_path / "pyenv"
                if pyenv_path.exists():
                    bin_dir = pyenv_path / "bin"
                    if bin_dir.exists():
                        # Expected path in published environment
                        expected_path = f"/home/jovyan/.qbraid/environments/{slug}/pyenv"

                        # Fix executable shebangs using centralized sanitization
                        for exe_file in bin_dir.iterdir():
                            if exe_file.is_file() and os.access(exe_file, os.X_OK):
                                try:
                                    with open(exe_file, "rb") as f:
                                        content = f.read()

                                    # Use centralized shebang sanitization
                                    new_content = _sanitize_shebang_for_upload(content, slug)

                                    if new_content != content:
                                        with open(exe_file, "wb") as out_f:
                                            out_f.write(new_content)
                                except (OSError, UnicodeDecodeError) as err:
                                    logger.warning("Failed to fix shebang in %s: %s", exe_file, err)

                        # Fix activation script VIRTUAL_ENV and other paths
                        for activate_name in ["activate", "activate.csh", "activate.fish"]:
                            activate_script = bin_dir / activate_name
                            if activate_script.exists():
                                try:
                                    with open(activate_script, "r", encoding="utf-8") as f:
                                        text_content = f.read()

                                    # Sanitize all user-specific paths
                                    new_text_content = _sanitize_path_for_upload(text_content, slug)

                                    # Also normalize any remaining embedded pyenv
                                    # paths to the published slug location
                                    # (quote-agnostic). Intentionally narrower
                                    # than the old VIRTUAL_ENV="..." sweep: only
                                    # paths matching the .qbraid/environments/*/
                                    # pyenv shape are rewritten, so a stray
                                    # non-canonical build path (e.g. /tmp/build/
                                    # pyenv) is left as-is here -- it would be
                                    # relocated on install only if it matches.
                                    new_text_content = rewrite_env_pyenv_paths(
                                        new_text_content, expected_path
                                    )

                                    if new_text_content != text_content:
                                        with open(activate_script, "w", encoding="utf-8") as f:
                                            f.write(new_text_content)
                                except (OSError, UnicodeDecodeError) as err:
                                    logger.warning("Failed to fix %s: %s", activate_name, err)

                    # Fix pyvenv.cfg - strip machine-specific fields, keep version info
                    pyvenv_cfg = pyenv_path / "pyvenv.cfg"
                    if pyvenv_cfg.exists():
                        try:
                            with open(pyvenv_cfg, "r", encoding="utf-8") as f:
                                lines = f.readlines()

                            # Keep only portable fields, strip
                            # machine-specific paths.
                            # Keep: version, include-system-site-packages
                            # Strip: home, executable, command
                            portable_fields = {"version", "include-system-site-packages"}
                            new_lines = []
                            for line in lines:
                                stripped = line.strip()
                                if not stripped or stripped.startswith("#"):
                                    new_lines.append(line)
                                    continue
                                key = stripped.split("=")[0].strip().lower()
                                if key in portable_fields:
                                    new_lines.append(line)

                            with open(pyvenv_cfg, "w", encoding="utf-8") as f:
                                f.writelines(new_lines)
                        except (OSError, UnicodeDecodeError) as err:
                            logger.warning("Failed to fix pyvenv.cfg: %s", err)

                # Fix kernel.json paths
                kernels_dir = slug_env_path / "kernels"
                if kernels_dir.exists():
                    for kernel_dir in kernels_dir.iterdir():
                        if not kernel_dir.is_dir():
                            continue
                        kernel_json = kernel_dir / "kernel.json"
                        if kernel_json.exists():
                            try:
                                with open(kernel_json, "r", encoding="utf-8") as f:
                                    kernel_data = json.load(f)

                                # Update argv[0] to generic path
                                if "argv" in kernel_data and kernel_data["argv"]:
                                    expected_python = (
                                        f"/home/jovyan/.qbraid/environments/{slug}/pyenv/bin/python"
                                    )
                                    kernel_data["argv"][0] = expected_python

                                    with open(kernel_json, "w", encoding="utf-8") as f:
                                        json.dump(kernel_data, f, indent=1)
                            except (json.JSONDecodeError, OSError) as err:
                                logger.warning(
                                    "Failed to fix kernel.json at %s: %s", kernel_json, err
                                )

            await asyncio.to_thread(_prepare_environment_copy)

            # Sanitize qbraid.yaml for upload (remove user-specific data)
            EnvironmentRegistryManager.sanitize_manifest_for_upload(slug_env_path)

            if progress_callback:
                progress_callback("prepare", 2, 3)

            # Step 3: Get upload signed URL from API
            try:
                response = self.session.post(
                    f"/environments/{slug}/upload-url",
                    json={"action": "publish", "overwrite": overwrite},
                )
                response.raise_for_status()
                data = response.json()

                # Handle new API response format: {success: true, data: {uploadUrl: ...}}
                if isinstance(data, dict) and data.get("success") and "data" in data:
                    upload_url = data["data"].get("uploadUrl")
                else:
                    # Legacy format fallback
                    upload_url = data.get("signedUrl") or data.get("uploadUrl")

                if not upload_url:
                    raise EnvironmentServiceRequestError(
                        f"Upload URL not found in API response for '{slug}'"
                    )
            except RequestsApiError as err:
                raise EnvironmentServiceRequestError(
                    f"Failed to get upload URL for environment '{slug}': {err}"
                ) from err

            if progress_callback:
                progress_callback("prepare", 3, 3)

            try:
                # Step 4: Create archive preserving symlinks
                def _create_archive() -> str:
                    """Create compressed archive synchronously, preserving symlinks."""
                    with tempfile.NamedTemporaryFile(
                        suffix=".tar.zst", delete=False
                    ) as temp_archive:
                        archive_path = temp_archive.name

                        # Create tar archive preserving symlinks (default behavior)
                        with tarfile.open(archive_path, "w") as tar:
                            tar.add(slug_env_path, arcname=slug)
                            # Note: tarfile.add() preserves symlinks by default

                        # Compress with zstd
                        compressed_path = archive_path + ".compressed"
                        with open(archive_path, "rb") as f_in:
                            with open(compressed_path, "wb") as f_out:
                                import zstandard as zstd  # pylint: disable=import-outside-toplevel

                                cctx = zstd.ZstdCompressor()
                                cctx.copy_stream(f_in, f_out)

                        # Replace original with compressed
                        Path(archive_path).unlink()
                        Path(compressed_path).rename(archive_path)

                        if progress_callback:
                            archive_size = Path(archive_path).stat().st_size
                            progress_callback("archive", archive_size, archive_size)

                        return archive_path

                # Run archive creation in thread pool
                archive_path = await asyncio.to_thread(_create_archive)

                # Step 5: Upload to GCS using signed URL
                def _upload_archive() -> None:
                    """Upload archive synchronously."""
                    archive_size = Path(archive_path).stat().st_size

                    with open(archive_path, "rb") as f:
                        # Use requests to upload with progress
                        # Use longer timeout for uploads (10 min) - large envs can take a while
                        response = self.session.put(
                            upload_url,
                            data=f,
                            headers={"Content-Type": "application/zstd"},
                            timeout=600,
                        )
                        response.raise_for_status()

                        if progress_callback:
                            progress_callback("upload", archive_size, archive_size)

                # Run upload in thread pool
                await asyncio.to_thread(_upload_archive)

                # Clean up archive
                Path(archive_path).unlink(missing_ok=True)

                # Update registry with slug and groups
                try:
                    entry = registry_mgr.get_environment(env_id)
                    entry.slug = slug
                    # Update groups if we added to a group
                    if effective_group_slug:
                        if entry.groups is None:
                            entry.groups = [effective_group_slug]
                        elif effective_group_slug not in entry.groups:
                            entry.groups.append(effective_group_slug)
                    registry_mgr.save_registry()
                    logger.info("Updated registry with slug %s for env_id %s", slug, env_id)
                except Exception as reg_err:
                    logger.warning("Failed to update registry with slug: %s", reg_err)

                # Confirm upload with API (verifies file exists in GCS, sets envS3Url)
                bucket = data.get("bucket", "qbraid-envs-staging")
                gcs_path = f"{slug}_environment.tar.zst"
                try:
                    confirm_result = self.confirm_upload(slug)
                    logger.info(
                        "Upload confirmed for %s: %s",
                        slug,
                        confirm_result.get("message", "success"),
                    )
                except Exception as confirm_err:
                    logger.warning("Failed to confirm upload: %s", confirm_err)
                    # Upload succeeded but confirmation failed - environment may not be downloadable
                    raise EnvironmentOperationError(
                        f"Upload completed but confirmation failed for '{slug}': {confirm_err}"
                    ) from confirm_err

                return {
                    "status": "success",
                    "slug": slug,
                    "env_id": env_id,
                    "bucket": bucket,
                    "path": gcs_path,
                }

            except Exception as err:
                # Clean up on failure
                if "archive_path" in locals():
                    Path(archive_path).unlink(missing_ok=True)

                raise EnvironmentOperationError(
                    f"Failed to publish environment '{identifier}': {err}"
                ) from err

    async def _relocate_environment_paths(self, env_path: Path):
        """Fix hardcoded paths in relocated environment.

        Note:
            This operation is Lab/POSIX-specific and only runs in qBraid Lab.

        Raises:
            EnvironmentOperationError: If not running in qBraid Lab
        """
        # Path relocation fixes hardcoded paths after downloading/extracting
        # an environment. Safe to run on any platform.

        pyenv_path = env_path / "pyenv"
        if not pyenv_path.exists():
            return

        def _fix_paths() -> None:
            """Fix executable shebangs and activation script paths."""
            bin_dir = pyenv_path / "bin"
            if not bin_dir.exists():
                return

            # Fix executable shebangs
            shebang_pattern = re.compile(r"^#!.*\.qbraid/environments/.*/pyenv/bin/python3")
            new_shebang = f"#!{pyenv_path}/bin/python3"

            for exe_file in bin_dir.iterdir():
                if exe_file.is_file() and os.access(exe_file, os.X_OK):
                    try:
                        with open(exe_file, "rb") as f:
                            first_line = f.readline()
                            if first_line.startswith(b"#!"):
                                # Read the rest of the file
                                content = first_line + f.read()
                                text_content = content.decode("utf-8", errors="ignore")
                                if shebang_pattern.match(text_content.split("\n")[0]):
                                    # Replace shebang
                                    lines = text_content.split("\n")
                                    lines[0] = new_shebang
                                    new_content = "\n".join(lines).encode("utf-8")
                                    with open(exe_file, "wb") as out_f:
                                        out_f.write(new_content)
                    except (OSError, UnicodeDecodeError) as err:
                        logger.warning("Failed to fix shebang in %s: %s", exe_file, err)

            # Fix activation script VIRTUAL_ENV (quote-agnostic; covers the
            # unquoted and cygpath forms emitted by modern uv/py3.12 venvs).
            for activate_name in ("activate", "activate.csh", "activate.fish"):
                activate_script = bin_dir / activate_name
                if not activate_script.exists():
                    continue
                try:
                    with open(activate_script, "r", encoding="utf-8") as f:
                        activate_content = f.read()

                    new_activate_content = rewrite_env_pyenv_paths(activate_content, pyenv_path)

                    if new_activate_content != activate_content:
                        with open(activate_script, "w", encoding="utf-8") as f:
                            f.write(new_activate_content)
                except (OSError, UnicodeDecodeError) as err:
                    logger.warning("Failed to fix activation script %s: %s", activate_name, err)

        await asyncio.to_thread(_fix_paths)

    async def uninstall_environment_local(
        self, identifier: str, delete_metadata: bool = False, force: bool = False
    ) -> dict[str, Any]:
        """Uninstall a locally installed environment.

        Removes the environment directory from the local filesystem. Cloud
        metadata is preserved by default so the same slug can be reinstalled
        later; pass ``delete_metadata=True`` to also delete the cloud copy.

        Args:
            identifier: Environment name or env_id to uninstall.
            delete_metadata: If True, also delete environment from API
                (requires slug and ownership). Default False — the local
                install is removed but the cloud environment is preserved.
                Set True only when the caller intends to retire the cloud
                environment entirely.
            force: If True, skip confirmation prompts. Default False.

        Returns:
            dict[str, Any]: Result with keys ``status``, ``env_id``, ``slug``,
                ``path``, ``deleted_metadata`` (True only if cloud delete was
                requested AND succeeded), and ``removed_kernels`` (list of
                Jupyter kernelspec names that were unregistered — includes
                both the standard ``<env>/kernels/`` specs and any extras
                self-registered by env-startup hooks).

        Raises:
            EnvironmentValidationError: If name conflicts and env_id not provided.
            EnvironmentRegistryError: If environment not found in registry.
            EnvironmentInstallError: If local removal fails.

        Example:
            >>> emc = EnvironmentManagerClient()
            >>> result = await emc.uninstall_environment_local('qiskit')  # by name
            >>> result = await emc.uninstall_environment_local('a1b2')  # by env_id
        """
        registry_mgr = EnvironmentRegistryManager()

        # Try to find by name first, then by env_id
        entry = None
        env_id = None

        found_by_name = registry_mgr.find_by_name(identifier)
        if found_by_name:
            env_id, entry = found_by_name
        else:
            found_by_id = registry_mgr.find_by_env_id(identifier)
            if found_by_id:
                env_id, entry = found_by_id
            else:
                raise EnvironmentRegistryError(
                    f"Environment '{identifier}' not found. "
                    "Use name (if unique) or env_id to reference the environment."
                )

        env_path = entry.path

        if not force:
            logger.warning("Removing environment at %s", env_path)

        try:
            # Remove kernels from Jupyter's registry BEFORE deleting the env dir,
            # so the sweep can still resolve argv[0] paths inside the env. Covers
            # both the standard <env>/kernels/ specs and self-registered extras
            # (see docs/bundling-native-deps-and-kernels.md §6).
            removed_kernels: list[str] = []
            try:
                from .kernels import remove_kernels

                removed_kernels = remove_kernels(env_id)
                if removed_kernels:
                    logger.info(
                        "Removed %d kernel(s) for environment %s: %s",
                        len(removed_kernels),
                        env_id,
                        ", ".join(removed_kernels),
                    )
                else:
                    logger.debug("No kernels to remove for environment %s", env_id)
            except Exception as kern_err:
                logger.warning("Failed to remove kernels for %s: %s", env_id, kern_err)

            # Remove local directory
            shutil.rmtree(env_path)
            logger.info("Removed environment directory: %s", env_path)

            # Remove from registry
            try:
                registry_mgr.unregister_environment(env_id)
                logger.debug("Removed environment from registry: %s", env_id)
            except Exception as err:
                raise EnvironmentRegistryError(
                    f"Failed to unregister environment '{env_id}' from registry: {err}"
                ) from err

            metadata_deleted = False

            # Optionally delete from API (requires slug)
            if delete_metadata and entry.slug:
                try:
                    self.delete_environment(entry.slug)
                    metadata_deleted = True
                    logger.info("Deleted environment metadata from API: %s", entry.slug)
                except Exception as err:
                    logger.warning("Failed to delete metadata for %s: %s", entry.slug, err)

            return {
                "status": "success",
                "env_id": env_id,
                "slug": entry.slug,
                "path": str(env_path),
                "deleted_metadata": metadata_deleted,
                "removed_kernels": removed_kernels,
            }

        except EnvironmentRegistryError:
            raise
        except Exception as err:
            raise EnvironmentInstallError(
                f"Failed to uninstall environment '{identifier}': {err}"
            ) from err

    def register_external_environment(
        self,
        path: Path,
        name: Optional[str] = None,
        metadata: Optional[dict] = None,
    ) -> dict[str, Any]:
        """Register an external Python environment with qBraid.

        Args:
            path: Path to the Python environment directory
            name: Environment name. If None, uses directory name.
            metadata: Additional metadata to store

        Returns:
            dict[str, Any]: Registration result with env_id, name, and path

        Raises:
            EnvironmentValidationError: If the provided path is invalid or name conflicts.
            EnvironmentRegistryError: If registration fails.

        Example:
            >>> emc = EnvironmentManagerClient()
            >>> result = emc.register_external_environment(
            ...     Path('/home/user/conda/envs/my_env'),
            ...     name='myenv'
            ... )
            >>> print(result)
            {'env_id': 'a1b2', 'name': 'myenv', 'path': '/home/user/conda/...'}
        """
        # Validate path
        if not path.exists() or not path.is_dir():
            raise EnvironmentValidationError(f"Path does not exist or is not a directory: {path}")

        # Find Python executable
        python_candidates = [
            path / "bin" / "python",
            path / "bin" / "python3",
            path / "Scripts" / "python.exe",
        ]

        python_path = None
        for candidate in python_candidates:
            if is_valid_python(candidate):
                python_path = candidate
                break

        if not python_path:
            raise EnvironmentValidationError(f"No valid Python executable found in {path}")

        # Generate name if not provided
        if not name:
            name = path.name

        # Get Python version
        try:
            python_version = get_python_version(Path(python_path))
        except Exception as err:
            logger.warning("Failed to get Python version: %s", err)
            python_version = "unknown"

        # Prepare metadata
        env_metadata = metadata or {}
        env_metadata.update(
            {
                "python_version": python_version,
                "python_path": str(python_path),
                "original_path": str(path.resolve()),
            }
        )

        # Register in registry
        registry_mgr = EnvironmentRegistryManager()
        try:
            env_id = registry_mgr.register_environment(
                path=path,
                env_type="external",
                name=name,
                slug=None,  # External environments don't have cloud slugs
                is_temporary=False,
                metadata=env_metadata,
            )
        except ValueError as name_err:
            # Name conflict
            raise EnvironmentValidationError(
                f"{name_err}. Please use the env_id to reference this environment."
            ) from name_err
        except Exception as err:
            raise EnvironmentRegistryError(
                f"Failed to register external environment: {err}"
            ) from err

        logger.info("Registered external environment: %s (env_id: %s) at %s", name, env_id, path)

        # Update registry with local packages only
        _update_registry_packages(env_id)

        return {
            "env_id": env_id,
            "name": name,
            "path": str(path),
            "python_version": python_version,
        }

    def unregister_external_environment(self, identifier: str) -> dict[str, Any]:
        """Unregister an external environment from qBraid.

        This only removes the environment from the registry. The actual files
        are NOT deleted.

        Args:
            identifier: Environment name or env_id to unregister

        Returns:
            dict[str, Any]: Unregistration result

        Raises:
            EnvironmentValidationError: If name conflicts and env_id not provided.
            EnvironmentRegistryError: If environment not found or is not external

        Example:
            >>> emc = EnvironmentManagerClient()
            >>> result = emc.unregister_external_environment('myenv')  # by name
            >>> result = emc.unregister_external_environment('a1b2')  # by env_id
        """
        registry_mgr = EnvironmentRegistryManager()

        # Try to find by name first, then by env_id
        entry = None
        env_id = None

        found_by_name = registry_mgr.find_by_name(identifier)
        if found_by_name:
            env_id, entry = found_by_name
        else:
            found_by_id = registry_mgr.find_by_env_id(identifier)
            if found_by_id:
                env_id, entry = found_by_id
            else:
                raise EnvironmentRegistryError(
                    f"Environment '{identifier}' not found. "
                    "Use name (if unique) or env_id to reference the environment."
                )

        if entry.type != "external":
            raise EnvironmentRegistryError(
                f"Environment '{identifier}' is type '{entry.type}', not 'external'. "
                f"Use uninstall_environment_local() for qBraid-managed environments."
            )

        path = entry.path
        registry_mgr.unregister_environment(env_id)
        logger.info("Unregistered external environment: %s (env_id: %s)", entry.name, env_id)

        return {
            "status": "success",
            "env_id": env_id,
            "name": entry.name,
            "path": str(path),
        }

    def sync_registry(self) -> dict[str, int]:
        """Synchronize environment registry with filesystem.

        This will:
        - Remove registry entries where paths no longer exist
        - Auto-discover new qBraid environments in default paths
        - Verify all registered environments still exist

        Returns:
            dict[str, int]: Statistics about sync operation
                - removed: Number of invalid entries removed
                - discovered: Number of new environments discovered
                - verified: Number of existing entries verified

        Example:
            >>> emc = EnvironmentManagerClient()
            >>> stats = emc.sync_registry()
            >>> print(stats)
            {'removed': 1, 'discovered': 2, 'verified': 5}
        """
        registry_mgr = EnvironmentRegistryManager()
        stats = registry_mgr.sync_with_filesystem()

        logger.info("Registry sync complete: %s", stats)
        return stats
